      "يحدث التحلل الغلايكولي في السيتوسول بغياب الأكسجين وينتج عنه جزيئا بيروفيت وجزيئا ATP وجزيئا NADH.",
      "يتطلب التنفس الهوائي وجود الأكسجين ويحدث داخل الميتوكندريا عبر ثلاث خطوات: أكسدة البيروفيت، وحلقة كربس، والفسفرة التأكسدية.",
