        "back": "اقترح العالمان مسلسون وستال (Meselson and Stahl) نموذج التضاعف شبه المحافظ، استناداً إلى اكتشاف تركيب الـ DNA على أيدي العالمين واتسون وكريك (Watson and Crick).",
