        "back": "سينتج جزيئان هجينان متماثلان؛ حيث يحتوي كل جزيء منهما على سلسلة واحدة قديمة (أصلية) تحتوي على النيتروجين الثقيل، وسلسلة واحدة جديدة مكملة تحتوي على النيتروجين الخفيف، لأن كل سلسلة أصلية تعمل كقالب لبناء سلسلة جديدة.",
