        "back": "من حيث تطابق تتابع النيوكليوتيدات: الجزيئان الناتجان متطابقان تماماً مع بعضهما ومع الجزيء الأصلي. من حيث مصدر السلاسل: الجزيء الأصلي يتكون من سلسلتين أصليتين بالكامل، بينما كل جزيء ناتج يتكون من سلسلة واحدة أصلية وسلسلة واحدة جديدة مكملة.",
