        "back": "في السيادة التامة، ينتج عن الأليلين طرازان شكليان فقط (سائد ومتنحي). أما في السيادة غير التامة، فينتج ثلاثة طرز شكلية (الصفة الأولى، الصفة الثانية، وصفة وسطية جديدة تظهر عند اجتماع الأليلين المختلفين معاً في الفرد غير متماثل الأليلات).",
